<script setup lang="ts">
import {onMounted,ref} from 'vue';import api from '../api';
const rows=ref<any[]>([]),name=ref(''),document=ref(''),email=ref(''),phone=ref(''),search=ref(''),message=ref('');
async function load(){const {data}=await api.get('/clients',{params:{search:search.value}});rows.value=data.data}
async function save(){message.value='';try{await api.post('/clients',{name:name.value,document:document.value,email:email.value,phone:phone.value});name.value='';document.value='';email.value='';phone.value='';message.value='Cliente cadastrado.';await load()}catch{message.value='Confira os campos e tente novamente.'}}
async function remove(id:number){if(confirm('Excluir este cliente?')){await api.delete(`/clients/${id}`);await load()}}
onMounted(load);
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">RELACIONAMENTO</p><h1>Clientes</h1><p class="muted">Gerencie os contatos e dados cadastrais.</p></div></div><div class="panel form-panel"><h2>Novo cliente</h2><form class="inline-form" @submit.prevent="save"><label>Nome<input v-model="name" required placeholder="Nome completo"/></label><label>CPF/CNPJ<input v-model="document" placeholder="Documento"/></label><label>E-mail<input v-model="email" type="email" placeholder="email@exemplo.com"/></label><label>Telefone<input v-model="phone" placeholder="(27) 99999-9999"/></label><button class="primary">Cadastrar cliente</button></form><p v-if="message" class="muted">{{message}}</p></div><div class="panel"><div class="panel-heading"><h2>Carteira de clientes</h2><input v-model="search" class="search" placeholder="Buscar cliente..." @input="load"/></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Documento</th><th>E-mail</th><th>Telefone</th><th></th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><b>{{c.name}}</b></td><td>{{c.document||'—'}}</td><td>{{c.email||'—'}}</td><td>{{c.phone||'—'}}</td><td><button class="danger-link" @click="remove(c.id)">Excluir</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty">Nenhum cliente cadastrado.</p></div></section></template>
